def header(title, desc):
    return f'''<!doctype html><html lang="en"><head><meta charset="utf-8"><meta name="viewport" content="width=device-width, initial-scale=1"><title>Knight Labs — {html.escape(title)}</title><meta name="description" content="{html.escape(desc)}"><link rel="icon" type="image/png" href="assets/knight-labs-crest-icon-transparent.png"><link href="https://fonts.googleapis.com/css2?family=DM+Sans:wght@400;500;700;900&display=swap" rel="stylesheet"><style>{css}</style></head><body>'''

def topbar(cta_href='supply-categories.html', cta='Shop Products'):
    return f'''<header class="wrap topbar"><a class="brand" href="index.html"><img src="assets/knight-labs-crest-icon-transparent.png" alt="Knight Labs crest"><span>Knight Labs</span></a><nav aria-label="Primary navigation"><a href="index.html">Home</a><a href="supply-categories.html">Shop</a><a href="index.html#quality">Quality</a><a href="index.html#wholesale">Wholesale</a><a href="mailto:hello@knightlabs.example">Contact</a><a class="nav-cta" href="{cta_href}">{cta}</a></nav></header>'''

def footer():
    return '''<footer class="footer"><div class="wrap"><div class="footer-logo"><img src="assets/knight-labs-crest-icon-transparent.png" alt="Knight Labs crest"><span>Knight Labs</span></div><p>For research and laboratory use only. Not intended for human or veterinary consumption. Nothing on this page is intended to diagnose, treat, cure, or prevent any disease. Product availability, labeling, and permitted uses may vary by jurisdiction.</p></div></footer></body></html>'''

def chips(formats):
    return ''.join(f'<span class="chip">{html.escape(x)}</span>' for x in formats)

def card(p, rank):
    popular = '<span class="badge">Most requested</span>' if rank == 0 else ''
    data = html.escape((p['name']+' '+p['type']+' '+' '.join(p['formats'])).lower())
    return f'''<article class="card" data-name="{data}"><div><div class="badges"><span class="badge avail">Available</span>{popular}<span class="badge">COA available</span></div><div class="product-photo"><img src="{ASSET}" alt="Knight Labs peptide vial"></div><h3>{html.escape(p['name'])}</h3><div class="type">{html.escape(p['type'])}</div><p class="desc">{html.escape(p['lead'])}</p><div class="formats"><small>Available sizes</small><div class="chips">{chips(p['formats'])}</div></div></div><div><div class="card-actions"><a class="btn primary" href="product-{p['slug']}.html">Select Options</a><button class="btn secondary" data-product="{html.escape(p['name'])}">View COA</button></div><p class="price-note">Choose size on the product page.</p></div></article>'''

bycat = {}
for p in products:
    bycat.setdefault(p['category_file'], []).append(p)

for fname, plist in bycat.items():
    title, heading, desc = category_meta[fname]
    doc = header(title, desc)
    doc += f'''<div class="hero">{topbar('#products','Browse Products')}<div class="wrap hero-inner"><div><div class="breadcrumb"><a href="supply-categories.html">Shop</a><span>/</span><span>{html.escape(title)}</span></div><div class="kicker">{html.escape(title)}</div><h1>{html.escape(title)}</h1><p class="lead">{html.escape(desc)}</p></div></div></div>'''
    doc += f'''<section id="products"><div class="wrap"><div class="section-head"><div><div class="kicker" style="color:#967016">Shop Products</div><h2 class="title">{html.escape(heading)}</h2><p>Products are ordered by expected popularity and customer demand.</p></div></div><div class="catalog-tools"><input class="search" type="search" placeholder="Search this category…" aria-label="Search products"></div><div class="product-grid" id="grid">{''.join(card(p,i) for i,p in enumerate(plist))}</div><div class="empty" id="empty">No available products match that search.</div></div></section>'''
    doc += '''<section class="trust"><div class="wrap"><div class="section-head"><div><div class="kicker" style="color:#967016">Quality Standard</div><h2 class="title">Product quality basics.</h2><p>Simple product pages with vial sizes, COAs, batch records, and checkout.</p></div></div><div class="trust-grid"><article class="trust-card"><small>01</small><h3>COA Availability</h3><p>Quality documents are requested and presented where available for applicable product lots.</p></article><article class="trust-card"><small>02</small><h3>Batch Records</h3><p>Products are tied to batch information when available.</p></article><article class="trust-card"><small>03</small><h3>Checkout Ready</h3><p>Select a size and add products to your cart.</p></article><article class="trust-card"><small>04</small><h3>Clear Boundaries</h3><p>No dosing instructions, disease positioning, human-use claims, or veterinary-use claims.</p></article></div></div></section>'''
    doc += '''<section><div class="wrap"><div class="disclaimer-band"><div><div class="kicker">Research Use Only</div><h2 class="title" style="font-size:clamp(32px,4vw,54px)">Research use only.</h2><p>Knight Labs products are intended for research and laboratory use only. Products are not intended for human or veterinary consumption.</p></div><a class="btn primary" href="#products">Shop Products</a></div></div></section><div class="toast" id="toast">COA preview placeholder.</div>'''
    doc += '''<script>const cards=[...document.querySelectorAll('.card')],search=document.querySelector('.search'),empty=document.querySelector('#empty');function apply(){const q=(search.value||'').toLowerCase().trim();let shown=0;cards.forEach(c=>{const show=!q||c.dataset.name.includes(q)||c.innerText.toLowerCase().includes(q);c.style.display=show?'flex':'none';if(show)shown++;});empty.style.display=shown?'none':'block';}search.addEventListener('input',apply);const toast=document.querySelector('#toast');document.querySelectorAll('[data-product]').forEach(b=>b.addEventListener('click',()=>{toast.textContent='COA preview placeholder for '+b.dataset.product;toast.classList.add('show');setTimeout(()=>toast.classList.remove('show'),1800);}));</script>'''
    doc += footer()
    (root / fname).write_text(doc, encoding='utf-8')

for p in products:
    opts = ''.join(f'<button class="option" data-size="{html.escape(size)}">{html.escape(size)}</button>' for size in p['formats'])
    details = '<div class="detail"><small>Status</small><b>Available</b></div><div class="detail"><small>COA</small><b>Available</b></div><div class="detail"><small>Use</small><b>Research only</b></div>'
    doc = header(p['name'], p['lead'])
    doc += f'''<div class="hero">{topbar('cart.html','Cart')}<div class="wrap hero-inner"><div><div class="breadcrumb"><a href="supply-categories.html">Shop</a><span>/</span><a href="{p['category_file']}">{html.escape(p['category'])}</a><span>/</span><span>{html.escape(p['name'])}</span></div><div class="kicker">{html.escape(p['type'])}</div><h1>{html.escape(p['name'])}</h1><p class="lead">{html.escape(p['lead'])}</p></div></div></div>'''
    doc += f'''<section><div class="wrap product-layout"><div class="product-stage"><img src="{ASSET}" alt="Knight Labs peptide vial"></div><div class="product-info"><div class="badges"><span class="badge avail">Available</span><span class="badge">COA available</span><span class="badge">Batch records</span></div><h2 class="title">Select vial size.</h2><p class="lead" style="color:var(--muted);font-size:18px">Choose a size for {html.escape(p['name'])}. Pricing can be added once retail margins are finalized.</p><div class="option-grid">{opts}</div><p class="price-note">Selected size: <b id="selected-size"></b></p><div class="qty"><label for="qty"><b>Quantity</b></label><input id="qty" type="number" min="1" value="1"></div><div class="detail-list">{details}</div><div class="card-actions"><a class="btn primary" id="add-cart" href="cart.html?add={p['slug']}">Add to Cart</a><button class="btn secondary" onclick="alert('COA preview placeholder for {html.escape(p['name'])}')">View COA</button></div><p class="price-note">For research and laboratory use only. Not intended for human or veterinary consumption.</p></div></div></section>'''
    doc += f'''<script>const options=[...document.querySelectorAll('.option')];let selected={json.dumps(p['formats'][0])};const sizeOut=document.querySelector('#selected-size');const add=document.querySelector('#add-cart');const qty=document.querySelector('#qty');function update(){{sizeOut.textContent=selected;add.href='cart.html?add={p['slug']}&size='+encodeURIComponent(selected)+'&qty='+encodeURIComponent(qty.value||1);}}options.forEach((b,i)=>{{if(i===0)b.classList.add('active');b.addEventListener('click',()=>{{options.forEach(x=>x.classList.remove('active'));b.classList.add('active');selected=b.dataset.size;update();}});}});qty.addEventListener('input',update);update();</script>'''
    doc += footer()
    (root / f"product-{p['slug']}.html").write_text(doc, encoding='utf-8')

