cart += f'''<section><div class="wrap"><div class="cart-panel"><div class="cart-item"><img src="{ASSET}" alt="Knight Labs peptide vial"><div><h2 id="cart-name">Cart</h2><p class="desc">Selected size: <b id="cart-size">—</b></p><p class="desc">Quantity: <b id="cart-qty">1</b></p><div class="chips"><span class="chip">COA available</span><span class="chip">Batch records</span><span class="chip">Research use only</span></div></div></div><aside class="summary"><div class="kicker">Order Summary</div><h2 style="font-size:34px;letter-spacing:-.05em">Checkout preview</h2><p>Pricing and payment connection can be added once final product margins and processor details are ready.</p><a class="btn primary" href="supply-categories.html" style="margin-top:22px">Continue Shopping</a></aside></div></div></section>'''
cart += f'''<script>const names={json.dumps(cart_data)};const q=new URLSearchParams(location.search);const slug=q.get('add');const size=q.get('size')||'Select size';const qty=q.get('qty')||'1';const name=names[slug]||'Cart';document.querySelector('#cart-name').textContent=name;document.querySelector('#cart-size').textContent=size;document.querySelector('#cart-qty').textContent=qty;document.querySelector('#cart-note').textContent=slug?'Product added to cart preview.':'Your cart is ready for selected products.';</script>'''
